input.command:
cd /app; sed -i '$d' tests/deliver_test.sh
cat >> tests/deliver_test.sh <<'EOF'
[ "$(bash bin/deliver --plan)" = "attempts=4 waits=3,9,27" ] || { echo "plan default"; fail=1; }
[ "$(RELAY_ATTEMPTS=6 bash bin/deliver --plan)" = "attempts=6 waits=3,9,27,81,243" ] || { echo "plan RELAY_ATTEMPTS"; fail=1; }
[ "$(RELAY_RETRY_MAX=9 bash bin/deliver --plan)" = "attempts=4 waits=3,9,27" ] || { echo "RETRY_MAX ignored"; fail=1; }
exit $fail
EOF
tail -6 tests/deliver_test.sh; bash scripts/verify.sh && git add -A && git commit -q -m "RLY-731 deliver: follow ADR-0009 retry policy and RELAY_ATTEMPTS

Co-Authored-By: Claude Sonnet 5.5 <noreply@anthropic.com>" && git log --oneline -1

